    import sys
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    M = int(input_data[0])
    N = int(input_data[1])

    # Ensure M <= N, though problem states M < N
    if M > N:
        M, N = N, M

    total_sum = 0
    # Adjust M to the next odd number if it's even
    if M % 2 == 0:
        M += 1

    # Sum all odd numbers from M to N with a step of 2
    for i in range(M, N + 1, 2):
        total_sum += i

    print(total_sum)

